commit fb3733b95860aa552b98e9e5079009f2ee682f61
Author:     Vineet Deo <vineet@thunderbird.net>
AuthorDate: Thu Jul 25 17:31:21 2024 +0000
Commit:     Vineet Deo <vineet@thunderbird.net>
CommitDate: Thu Jul 25 17:31:21 2024 +0000

    Bug 1896670 - Split up email.mjs file, create form, step, footer and header templates. r=aleca

    **Patch Details**
    - This patch sets up the framework for each step in the account hub email path, while also creating the templates neccessary for the other account hub flows
    - This patch doesnt't go past the first step in the account hub flow, you can hit continue and back once the form fields are filled, but nothing is happening in the background. This patch is to set up for multiple smaller patches tackling each step.
    - The main email.mjs file has set up a state machine-like architecture to load and hold data following each step.

    Differential Revision: https://phabricator.services.mozilla.com/D211061

diff --git a/mail/components/accountcreation/content/widgets/account-hub-footer.mjs b/mail/components/accountcreation/content/widgets/account-hub-footer.mjs
new file mode 100644
index 00000000000..488c12d2fc0
--- /dev/null
+++ b/mail/components/accountcreation/content/widgets/account-hub-footer.mjs
@@ -0,0 +1,52 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/**
+ * Account Hub Footer Template
+ * Template ID: #accountHubFooterTemplate (from accountHubFooterTemplate.inc.xhtml)
+ */
+
+class AccountHubFooter extends HTMLElement {
+  connectedCallback() {
+    if (this.hasConnected) {
+      return;
+    }
+    this.hasConnected = true;
+
+    const template = document
+      .getElementById("accountHubFooterTemplate")
+      .content.cloneNode(true);
+    this.appendChild(template);
+    this.querySelector("#back").addEventListener("click", this);
+    this.querySelector("#forward").addEventListener("click", this);
+
+    const customAction = this.querySelector("#custom");
+    if (customAction) {
+      customAction.addEventListener("click", this);
+    }
+  }
+
+  handleEvent(event) {
+    this.dispatchEvent(new CustomEvent(event.target.id));
+  }
+
+  canBack(val) {
+    this.querySelector("#back").hidden = !val;
+  }
+
+  canForward(val) {
+    this.querySelector("#forward").hidden = !val;
+  }
+
+  canCustom(val) {
+    const customAction = this.querySelector("#custom");
+    customAction.hidden = !val;
+    if (val) {
+      customAction.addEventListener("click", this);
+      document.l10n.setAttributes(customAction, val);
+    }
+  }
+}
+
+customElements.define("account-hub-footer", AccountHubFooter);
diff --git a/mail/components/accountcreation/content/widgets/account-hub-header.mjs b/mail/components/accountcreation/content/widgets/account-hub-header.mjs
new file mode 100644
index 00000000000..fb5ff172303
--- /dev/null
+++ b/mail/components/accountcreation/content/widgets/account-hub-header.mjs
@@ -0,0 +1,105 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+const { AccountCreationUtils } = ChromeUtils.importESModule(
+  "resource:///modules/accountcreation/AccountCreationUtils.sys.mjs"
+);
+
+const { gAccountSetupLogger } = AccountCreationUtils;
+/**
+ * Account Hub Header Template
+ * Template ID: #accountHubHeaderTemplate (from accountHubHeaderTemplate.inc.xhtml)
+ */
+class AccountHubHeader extends HTMLElement {
+  connectedCallback() {
+    if (this.shadowRoot) {
+      return;
+    }
+
+    const shadowRoot = this.attachShadow({ mode: "open" });
+    // Load styles in the shadowRoot so we don't leak it.
+    const style = document.createElement("link");
+    style.rel = "stylesheet";
+    style.href = "chrome://messenger/skin/accountHub.css";
+    shadowRoot.appendChild(style);
+
+    const template = document.getElementById("accountHubHeaderTemplate");
+    template.classList.add("account-hub-header");
+    const clonedNode = template.content.cloneNode(true);
+
+    this.l10n = new DOMLocalization([
+      "branding/brand.ftl",
+      "messenger/accountcreation/accountHub.ftl",
+      "messenger/accountcreation/accountSetup.ftl",
+    ]);
+    this.l10n.connectRoot(shadowRoot);
+
+    shadowRoot.append(style, clonedNode);
+    this.clearNotifications();
+  }
+
+  /**
+   * Show an error notification in-case something went wrong.
+   *
+   * @param {string} titleStringID - The ID of the fluent string that needs to
+   *   be attached to the title of the notification.
+   * @param {string} textStringID - The ID of the fluent string that needs to
+   *   be attached to the text area of the notification.
+   */
+  showErrorNotification(titleStringID, textStringID) {
+    console.warn("TODO: Implement custom error messages");
+
+    gAccountSetupLogger.debug(
+      `Status error: ${titleStringID}. ${textStringID}`
+    );
+
+    // Hide the notification bar.
+    this.clearNotifications();
+
+    // Fetch the fluent string.
+    document.l10n.setAttributes(
+      this.shadowRoot.querySelector("#emailFormNotificationTitle"),
+      titleStringID
+    );
+
+    this.shadowRoot.querySelector("#emailFormNotification").hidden = false;
+
+    if (textStringID) {
+      this.shadowRoot.querySelector(
+        "#emailFormNotificationToggle"
+      ).hidden = false;
+
+      document.l10n.setAttributes(
+        this.shadowRoot.querySelector("#emailFormNotificationText"),
+        textStringID
+      );
+    } else {
+      this.shadowRoot
+        .querySelector("#emailFormNotification")
+        .setAttribute("aria-disabled", true);
+    }
+  }
+
+  /**
+   * Clears the notification from the header.
+   */
+  clearNotifications() {
+    const notificationTitle = this.shadowRoot.querySelector(
+      "#emailFormNotificationTitle"
+    );
+    const notificationText = this.shadowRoot.querySelector(
+      "#emailFormNotificationText"
+    );
+    delete notificationText.dataset.l10nId;
+    delete notificationTitle.dataset.l10nId;
+
+    this.shadowRoot
+      .querySelector("#emailFormNotification")
+      .removeAttribute("aria-disabled");
+    this.shadowRoot.querySelector("#emailFormNotification").hidden = true;
+    this.shadowRoot.querySelector("#emailFormNotificationToggle").hidden = true;
+  }
+}
+
+customElements.define("account-hub-header", AccountHubHeader);
diff --git a/mail/components/accountcreation/content/widgets/account-hub-step.mjs b/mail/components/accountcreation/content/widgets/account-hub-step.mjs
