@@ -0,0 +1,90 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+import "chrome://messenger/content/accountcreation/content/widgets/account-hub-header.mjs"; // eslint-disable-line import/no-unassigned-import
+
+/**
+ * Account Hub Step Template
+ * Template ID: #accountHubStepTemplate (from accountHubStepTemplate.inc.xhtml)
+ *
+ * @slot header - Content displayed as the header.
+ * @slot subheader - Content displayed as the subheader
+ * @slot content - Body content for the step.
+ */
+export class AccountHubStep extends HTMLElement {
+  /** @type {DOMLocalization} */
+  l10n;
+
+  /**
+   * The header template.
+   *
+   * @type {HTMLElement}
+   */
+  #header;
+
+  async connectedCallback() {
+    if (this.shadowRoot) {
+      // Already connected, no need to run it again.
+      return;
+    }
+
+    const shadowRoot = this.attachShadow({ mode: "open" });
+
+    // Load styles in the shadowRoot so we don't leak it.
+    const style = document.createElement("link");
+    style.rel = "stylesheet";
+    style.href = "chrome://messenger/skin/accountHub.css";
+
+    const template = document.getElementById("accountHubStepTemplate");
+    const clonedNode = template.content.cloneNode(true);
+    shadowRoot.append(style, clonedNode);
+
+    this.l10n = new DOMLocalization([
+      "branding/brand.ftl",
+      "messenger/accountcreation/accountHub.ftl",
+      "messenger/accountcreation/accountSetup.ftl",
+    ]);
+    this.l10n.connectRoot(shadowRoot);
+    this.#header = this.shadowRoot.querySelector("account-hub-header");
+    this.#setHeader();
+  }
+
+  /**
+   * Applies the fluent ID's to the step's header text elements.
+   */
+  #setHeader() {
+    if (this.hasAttribute("title-id")) {
+      document.l10n.setAttributes(
+        this.shadowRoot.querySelector("#title"),
+        this.getAttribute("title-id")
+      );
+    }
+
+    if (this.hasAttribute("subheader-id")) {
+      document.l10n.setAttributes(
+        this.shadowRoot.querySelector("#subheader"),
+        this.getAttribute("subheader-id")
+      );
+    }
+  }
+
+  /**
+   * Calls the error notification method in the header template.
+   *
+   * @param {String} errorTitleID - The fluent ID of the error title.
+   * @param {String} errorTextID - The fluent ID of the error text.
+   */
+  showErrorNotification(errorTitleID, errorTextID = "") {
+    this.#header.showErrorNotification(errorTitleID, errorTextID);
+  }
+
+  /**
+   * Calls the clear notification method in the header template.
+   */
+  clearNotifications() {
+    this.#header.clearNotifications();
+  }
+}
+
+customElements.define("account-hub-step", AccountHubStep);
diff --git a/mail/components/accountcreation/content/widgets/email-auto-form.mjs b/mail/components/accountcreation/content/widgets/email-auto-form.mjs
new file mode 100644
index 00000000000..32b1dd793ec
--- /dev/null
+++ b/mail/components/accountcreation/content/widgets/email-auto-form.mjs
@@ -0,0 +1,107 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+import { AccountHubStep } from "./account-hub-step.mjs";
+
+/**
+ * Account Hub Email Auto Form Template
+ * Template ID: #accountHubEmailAutoFormTemplate (from accountHubEmailAutoFormTemplate.inc.xhtml)
+ */
+class EmailAutoForm extends AccountHubStep {
+  /**
+   * The account name field.
+   *
+   * @type {HTMLInputElement}
+   */
+  #realName;
+
+  /**
+   * The email field.
+   *
+   * @type {HTMLInputElement}
+   */
+  #email;
+
+  /**
+   * The current email auto config form inputs.
+   *
+   * @type {Object}
+   */
+  #currentConfig;
+
+  connectedCallback() {
+    if (this.hasConnected) {
+      return;
+    }
+
+    super.connectedCallback();
+    this.hasConnected = true;
+
+    const template = document
+      .getElementById("accountHubEmailAutoFormTemplate")
+      .content.cloneNode(true);
+    this.appendChild(template);
+
+    this.#realName = this.querySelector("#realName");
+    this.#email = this.querySelector("#email");
+    this.#currentConfig = {};
+
+    if ("@mozilla.org/userinfo;1" in Cc) {
+      const userInfo = Cc["@mozilla.org/userinfo;1"].getService(Ci.nsIUserInfo);
+      this.#realName.value = userInfo.fullname;
+    }
+
+    this.#realName.focus();
+    this.#checkValidEmailForm();
+
+    this.setupEventListeners();
+  }
+
+  /**
+   * Set up the event listeners for this workflow.
+   */
+  setupEventListeners() {
+    // Auto email config event listeners.
+    this.#realName.addEventListener("input", () => {
+      this.#checkValidEmailForm();
+    });
+    this.#email.addEventListener("input", () => {
+      this.#checkValidEmailForm();
+    });
+  }
+
+  /**
+   * Check whether the user entered the minimum amount of information needed to
+   * update the hostname and domain for the complete form.
+   */
+  #checkValidEmailForm() {
+    const isValidForm =
+      this.#email.checkValidity() && this.#realName.checkValidity();
+    const domain = isValidForm
+      ? this.#email.value.split("@")[1].toLowerCase()
+      : "";
+    const outgoingHostname = domain;
+    const incomingHostname = domain;
+    const incomingUsername = isValidForm ? this.#email.value : "";
+    const outgoingUsername = isValidForm ? this.#email.value : "";
+
+    this.#currentConfig = {
+      realName: this.#realName.value,
+      email: this.#email.value,
+      outgoingHostname,
+      incomingHostname,
+      outgoingUsername,
+      incomingUsername,
+    };
+  }
+
+  /**
+   * Return the current state of the email setup form.
+   */
+  captureState() {
+    return this.#currentConfig;
+  }
+}
+
+customElements.define("email-auto-form", EmailAutoForm);
